# [v76] 幂等写入 cron (先移除所有旧条目再添加,避免重复 + 清理 v75 遗留的 clear_haraka_queue.sh 条目)
(crontab -l 2>/dev/null \
    | grep -v 'clear_haraka_logs.sh' \
    | grep -v 'clear_haraka_queue.sh' \
    | grep -v 'extract_and_clear.py'; \
