# ===== Part 5: 系统级收尾 =====
mkdir -p /data/tasks /opt/phpmailer-injector

# [v76] swap 从 2G 幂等升级到 4G (支持从 Haraka06 2G swap 平滑升级)
# 4G 大小覆盖 Haraka + phpmailer-injector 高负载峰值 (~3GB) + 余量
NEED_CREATE_SWAP=1
if [ -f /swapfile ]; then
    CURRENT_SWAP_SIZE=$(stat -c '%s' /swapfile 2>/dev/null || echo 0)
    # 4G = 4294967296 字节
    if [ "$CURRENT_SWAP_SIZE" -ge 4294967296 ]; then
        NEED_CREATE_SWAP=0
    else
        # 现有 swap 小于 4G,先关闭再删除,为重建做准备
        swapoff /swapfile 2>/dev/null || true
        rm -f /swapfile
    fi
fi
if [ "$NEED_CREATE_SWAP" = "1" ]; then
    fallocate -l 4G /swapfile && chmod 600 /swapfile && mkswap /swapfile && swapon /swapfile
    grep -q '/swapfile' /etc/fstab || echo '/swapfile swap swap defaults 0 0' >> /etc/fstab
fi

# [v79 Haraka11] 启用 noatime,nodiratime 减少 HDD 写入 (幂等)
# 原因: HDD pd-standard 场景下, 每次读文件默认都会更新 atime (一次磁盘写)
# 加 noatime 后, Haraka 队列处理的磁盘写入量减少约 33%
if ! mount | grep -qE 'on / .*noatime'; then
    # 备份 fstab (以防 awk 处理出问题)
    cp /etc/fstab /etc/fstab.bak.haraka11 2>/dev/null || true
    # 用 awk 精确定位根分区 ext4 行, 修改第 4 列挂载选项
    awk '/^[[:space:]]*#/{print;next} $2=="/" && $3=="ext4" && $4 !~ /noatime/ {if($4=="defaults"){$4="defaults,noatime,nodiratime"}else{$4=$4",noatime,nodiratime"}} {print}' /etc/fstab.bak.haraka11 > /etc/fstab.new 2>/dev/null
    if [ -s /etc/fstab.new ]; then
        mv /etc/fstab.new /etc/fstab
        mount -o remount,noatime,nodiratime / 2>/dev/null || true
        echo "[v79 Haraka11] 已启用 noatime,nodiratime 挂载"
    else
        rm -f /etc/fstab.new
        echo "[v79 Haraka11] WARNING: fstab 改写失败, 跳过 noatime"
    fi
else
    echo "[v79 Haraka11] noatime 已启用, 跳过"
fi

